def find_component_boundary_distance(grid, target=0):
    """For each 0, compute its distance to the nearest non-0 neighbor (or grid edge)"""
    h, w = len(grid), len(grid[0])
    result = np.full((h, w), -1, dtype=int)

    # BFS from all cells that will be distance 0 (on boundary or target 0s)
    queue = deque()

    for r in range(h):
        for c in range(w):
            if grid[r, c] != target:
                queue.append((r, c, 0))
            elif grid[r, c] == target:
                # For target 0s, also check if they're on the boundary
                # We'll compute distances by BFS from all non-target cells
                pass

    # Actually, let me do this simpler: BFS from all non-0 cells, computing distance to each 0
    dist_map = {}

    for r in range(h):
        for c in range(w):
            if grid[r, c] != target:
                # Non-0 cell: source with distance 0, but we want to compute distance TO 0s
                pass

    # Better approach: For each 0, compute minimum distance to any non-0 (or grid edge)
    for r in range(h):
        for c in range(w):
            if grid[r, c] != target:
                continue  # Not a 0, skip
            dist_by_source = []
            for sr in range(h):
                for sc in range(w):
                    if grid[sr, sc] != target:
                        # Distance from (r,c) to the nearest non-0
                        dist = abs(r - sr) + abs(c - sc)
                        if (sr, sc) not in dist_by_source:
                            dist_by_source.append(dist)
            dist_by_source.append(0)  # Grid boundary at dist 0
            dist_map[(r, c)] = min(dist_by_source)

    return dist_map

